metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "ko"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "a_star(graph, start, goal, h)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "g = {start: 0}    # 출발점에서 온 비용"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "came_from = {}"
        },
        {
          "id": "b3",
          "kind": "process",
          "text": "open = [(h(start), start)]"
        },
        {
          "id": "b4",
          "kind": "while",
          "text": "open",
          "body": [
            {
              "id": "b5",
              "kind": "process",
              "text": "f, u = heappop(open)"
            },
            {
              "id": "b6",
              "kind": "if",
              "text": "f > g[u] + h(u)",
              "yes": {
                "id": "r1",
                "body": [
                  {
                    "id": "b7",
                    "kind": "process",
                    "text": "continue    # 낡은 항목: 그 뒤에 더 짧은 길을 찾았다"
                  }
                ]
              },
              "no": {
                "id": "r2",
                "body": [
                  {
                    "id": "b8",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b9",
              "kind": "if",
              "text": "u == goal",
              "yes": {
                "id": "r3",
                "body": [
                  {
                    "id": "b10",
                    "kind": "call",
                    "target": {
                      "kind": "local",
                      "diagram": "d2"
                    },
                    "args": "came_from, u",
                    "result": "path"
                  },
                  {
                    "id": "b11",
                    "kind": "process",
                    "text": "return path"
                  }
                ]
              },
              "no": {
                "id": "r4",
                "body": [
                  {
                    "id": "b12",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b13",
              "kind": "for",
              "text": "for v, w in graph[u]",
              "body": [
                {
                  "id": "b14",
                  "kind": "process",
                  "text": "tentative = g[u] + w"
                },
                {
                  "id": "b15",
                  "kind": "if",
                  "text": "tentative < g.get(v, INF)",
                  "yes": {
                    "id": "r5",
                    "body": [
                      {
                        "id": "b16",
                        "kind": "process",
                        "text": "came_from[v] = u    # 더 짧은 길을 찾았다"
                      },
                      {
                        "id": "b17",
                        "kind": "process",
                        "text": "g[v] = tentative"
                      },
                      {
                        "id": "b18",
                        "kind": "process",
                        "text": "heappush(open, (tentative + h(v), v))"
                      }
                    ]
                  },
                  "no": {
                    "id": "r6",
                    "body": [
                      {
                        "id": "b19",
                        "kind": "process",
                        "text": ""
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "b20",
          "kind": "process",
          "text": "return None    # 길이 없다"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "reconstruct(came_from, u)"
      },
      "body": [
        {
          "id": "b21",
          "kind": "process",
          "text": "path = [u]"
        },
        {
          "id": "b22",
          "kind": "while",
          "text": "u in came_from",
          "body": [
            {
              "id": "b23",
              "kind": "process",
              "text": "u = came_from[u]"
            },
            {
              "id": "b24",
              "kind": "process",
              "text": "path.append(u)"
            }
          ]
        },
        {
          "id": "b25",
          "kind": "process",
          "text": "return path[::-1]"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
